func TestEnumAccountUnreadReason(t *testing.T) {
	t.Run("NewFromString_disabled", func(t *testing.T) {
		t.Parallel()
		val, err := NewAccountUnreadReasonFromString("disabled")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, AccountUnreadReason("disabled"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_disconnected", func(t *testing.T) {
		t.Parallel()
		val, err := NewAccountUnreadReasonFromString("disconnected")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, AccountUnreadReason("disconnected"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_platformUnreachable", func(t *testing.T) {
		t.Parallel()
		val, err := NewAccountUnreadReasonFromString("platformUnreachable")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, AccountUnreadReason("platformUnreachable"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_rateLimited", func(t *testing.T) {
		t.Parallel()
		val, err := NewAccountUnreadReasonFromString("rateLimited")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, AccountUnreadReason("rateLimited"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_reconnect", func(t *testing.T) {
		t.Parallel()
		val, err := NewAccountUnreadReasonFromString("reconnect")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, AccountUnreadReason("reconnect"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewAccountUnreadReasonFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewAccountUnreadReasonFromString("disabled")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

